basicInfo.customCss:
@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.min.css");
@import url("https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Myeongjo:wght@400;700;800&display=swap");

.story-content {
    font-family: "Pretendard Variable", Pretendard, -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
    font-size: 1rem;
    line-height: 1.8;
    color: #d5cea3;
    background-color: #1a120b;
    padding: 1.5rem;
    border-radius: 8px;
    letter-spacing: -0.01em;
}

.story-content h1, 
.story-content h2, 
.story-content .section-title {
    font-family: "Nanum Myeongjo", serif;
    color: #e5ba73;
    border-bottom: 1px solid rgba(229, 186, 115, 0.3);
    padding-bottom: 0.5rem;
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    font-weight: 800;
}

.story-content h3,
.story-content .subsection-title {
    font-family: "Nanum Myeongjo", serif;
    color: #c85c5c;
    margin-top: 1.2rem;
    font-weight: 700;
}

.story-content strong,
.story-content .highlight {
    color: #e5ba73;
    font-weight: 700;
}

.story-content .emphasis {
    color: #c85c5c;
    font-style: italic;
}

.character-bak { color: #90a4ae !important; font-weight: 700; }
.character-lee { color: #ff8a65 !important; font-weight: 700; }
.character-kim { color: #ffd54f !important; font-weight: 700; }
.character-yang { color: #f48fb1 !important; font-weight: 700; }

.script-direction {
    font-style: italic;
    color: #8d6e63;
    margin: 1rem 0;
    padding-left: 1rem;
    border-left: 2px solid #3e2723;
    font-size: 0.95rem;
}

.script-line {
    margin-bottom: 0.5rem;
}

.retro-box {
    background: rgba(213, 206, 163, 0.05);
    border: 1px double #e5ba73;
    padding: 1.2rem;
    margin: 1.5rem 0;
    position: relative;
}

.retro-box::before {
    content: "NOTICE";
    position: absolute;
    top: -10px;
    left: 20px;
    background: #1a120b;
    padding: 0 10px;
    font-size: 0.7rem;
    color: #e5ba73;
    letter-spacing: 0.2em;
}

.story-content ul {
    list-style: none;
    padding-left: 0;
}

.story-content li {
    position: relative;
    padding-left: 1.5rem;
    margin-bottom: 0.5rem;
}

.story-content li::before {
    content: "◈";
    position: absolute;
    left: 0;
    color: #e5ba73;
    font-size: 0.8rem;
}

.beginner-guide {
    margin-top: 2rem;
    padding: 1rem;
    background: rgba(229, 186, 115, 0.1);
    border-radius: 4px;
    border: 1px solid rgba(229, 186, 115, 0.2);
}

.beginner-guide h3 {
    margin-top: 0;
    font-size: 1.1rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.story-content hr {
    border: none;
    height: 1px;
    background: linear-gradient(90deg, transparent, #e5ba73, transparent);
    margin: 2rem 0;
}
